#include <bits/stdc++.h>
using namespace std;

const long long INF = 1e18;

struct Edge {
    int to;
    int len;
};

struct Cycle {
    long long len;
    vector<int> vertices;
};

int E, R;
vector<vector<Edge>> adj;
vector<bool> visited;
vector<int> parent;
vector<int> depth;
vector<long long> distRoot;
vector<Cycle> cycles;

void dfs(int u, int p, int d, long long dist) {
    visited[u] = true;
    parent[u] = p;
    depth[u] = d;
    distRoot[u] = dist;

    for (const auto& e : adj[u]) {
        int v = e.to;
        int w = e.len;
        if (v == p) continue;

        if (!visited[v]) {
            dfs(v, u, d + 1, dist + w);
        } else {
            if (depth[v] < depth[u]) {
                vector<int> verts;
                long long cycleLen = distRoot[u] - distRoot[v] + w;
                int cur = u;
                while (cur != v) {
                    verts.push_back(cur);
                    cur = parent[cur];
                }
                verts.push_back(v);
                cycles.push_back({cycleLen, verts});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> E >> R;
    adj.assign(E + 1, {});

    for (int i = 0; i < R; ++i) {
        int A, B, C;
        cin >> A >> B >> C;
        adj[A].push_back({B, C});
        adj[B].push_back({A, C});
    }

    visited.assign(E + 1, false);
    parent.assign(E + 1, -1);
    depth.assign(E + 1, 0);
    distRoot.assign(E + 1, 0);

    for (int i = 1; i <= E; ++i) {
        if (!visited[i]) {
            dfs(i, -1, 0, 0);
        }
    }

    int K;
    cin >> K;

    while (K--) {
        int X, T;
        cin >> X >> T;

        vector<long long> dist(E + 1, INF);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
        dist[X] = 0;
        pq.push({0, X});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;

            for (const auto& e : adj[u]) {
                int v = e.to;
                int w = e.len;
                if (dist[v] > d + w) {
                    dist[v] = d + w;
                    pq.push({dist[v], v});
                }
            }
        }

        long long ans = INF;
        for (const auto& cyc : cycles) {
            if (cyc.len < T) continue;

            long long minDist = INF;
            for (int v : cyc.vertices) {
                if (dist[v] < minDist) {
                    minDist = dist[v];
                }
            }

            if (minDist != INF) {
                ans = min(ans, cyc.len + 2 * minDist);
            }
        }

        if (ans == INF) {
            cout << -1 << '\n';
        } else {
            cout << ans << '\n';
        }
    }

    return 0;
}
